Schritt 2: Erstellen einer SDL2-Anwendung

Nun erstellen wir eine SDL2-App, die die Grundlagen für unser Schlangenspiel bietet.

1. Erstellen Sie eine neue SDL2-Projektvorlage für Ihre bevorzugte Entwicklungsumgebung.

2. In der Hauptdatei Ihres Projekts, beispielsweise "main.c", fügen Sie folgenden Code hinzu:

```c
#include <SDL2/SDL.h>

int main(int argc, char* argv[]) {
    SDL_Init(SDL_INIT_VIDEO);

    SDL_Window* window = SDL_CreateWindow(
        "Snake Game",
        SDL_WINDOWPOS_CENTERED_DISPLAYSDL_DEFAULTDISPLAYINDEX,
        SDL_WINDOWPOS_CENTERED_DISPLAYSDL_DEFAULTDISPLAYINDEX,
        800, 600, SDL_WINDOW_SHOWN
    );

    SDL_Renderer* renderer = SDL_CreateRenderer(
        window,
        -1,
        SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC
    );

    SDL_SetRenderDrawColor(renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);

    bool running = true;
    while (running) {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = false;
            }
        }

        SDL_SetRenderDrawColor(renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);
        SDL_RenderClear(renderer);

        SDL_Delay(20);
        SDL_RenderPresent(renderer);
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
```

Dieser Code initialisiert SDL2 und erstellt eine leere SDL2-App mit einer Schritt-Frequenz von 50 fps.

Schritt 3: Hinzufügen von Grafik-Assets

Um das Schlangenspiel zu animieren, benötigen wir Grafik-Assets wie Bilder für die Schlange und das Level.

1. Laden Sie Ihre Grafik-Assets herunter und speichern Sie sie in Ihrem Projektverzeichnis.

2. Fügen Sie folgenden Code zum Hauptteil Ihres Programms hinzu, um Ihre Grafik-Assets zu laden:

```c
#include <SDL2/SDL.h>

#include <stdlib.h>
#include <stdio.h>

#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600

typedef struct {
    SDL_Texture* texture;
    int width;
    int height;
} Texture;

int main(int argc, char* argv[]) {
    SDL_Init(SDL_INIT_VIDEO);

    SDL_Window* window = SDL_CreateWindow(
        "Snake Game",
        SDL_WINDOWPOS_CENTERED_DISPLAYSDL_DEFAULTDISPLAYINDEX,
        SDL_WINDOWPOS_CENTERED_DISPLAYSDL_DEFAULTDISPLAYINDEX,
        WINDOW_WIDTH, WINDOW_HEIGHT, SDL_WINDOW_SHOWN
    );

    SDL_Renderer* renderer = SDL_CreateRenderer(
        window,
        -1,
        SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC
    );

    SDL_SetRenderDrawColor(renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);

    Texture snakeTexture;
    Texture groundTexture;

    // Lade die Texturen
    snakeTexture.texture = SDL_LoadBMP("snake.bmp");
    groundTexture.texture = SDL_LoadBMP("ground.bmp");

    if (!snakeTexture.texture || !groundTexture.texture) {
        printf("Failed to load textures.\n");
        SDL_DestroyRenderer(renderer);
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    snakeTexture.width = SDL_QueryTexture(snakeTexture.texture, NULL, NULL, &snakeTexture.height);
    groundTexture.width = SDL_QueryTexture(groundTexture.texture, NULL, NULL, &groundTexture.height);

    bool running = true;
    while (running) {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = false;
            }
        }

        SDL_SetRenderDrawColor(renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);
        SDL_RenderClear(renderer);

        // Zeichne die Schlange
        // ...

        // Zeichne das Level
        SDL_RenderCopy(renderer, groundTexture.texture, NULL, NULL, NULL);

        SDL_Delay(20);
        SDL_RenderPresent(renderer);
    }

    SDL_DestroyTexture(snakeTexture.texture);
    SDL_DestroyTexture(groundTexture.texture);

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
```

Ersetzen Sie "snake.bmp" und "ground.bmp" durch die Dateinamen Ihrer eigenen Texturen.

