Hier ist ein Beispiel C++-Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes in der Datei zählt:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>

int main() {
    std::string wordToCount; // Das Wort, nach dem gesucht werden soll
    std::string filePath; // Pfad zur Datei

    // Eingabe des Worts und des Dateipfades
    std::cout << "Geben Sie das zu zählende Wort ein: ";
    std::getline(std::cin, wordToCount);

    std::cout << "Geben Sie den Dateipfad ein: ";
    std::getline(std::cin, filePath);

    // Öffnen der Datei
    std::ifstream file(filePath);
    if (!file) {
        std::cerr << "Fehler: Die Datei konnte nicht geöffnet werden." << std::endl;
        return 1;
    }

    std::map<std::string, int> wordCounts; // Wörterbuch zum Speichern der Wortzählergebnisse

    // Zeilen für Zeilen lesen und Wort zählen
    std::string line;
    while (getline(file, line)) {
        std::size_t pos = 0;
        std::string currentWord;
        while ((pos = line.find(wordToCount, pos)) != std::string::npos) {
            currentWord = line.substr(pos, wordToCount.length());
            pos += wordToCount.length();
            if (wordCounts.find(currentWord) != wordCounts.end()) {
                wordCounts[currentWord]++;
            } else {
                wordCounts[currentWord] = 1;
            }
        }
    }

    // Ergebnisse ausgeben
    std::cout << "Wort\tVorkommen\n";
    for (auto const& entry : wordCounts) {
        std::cout << entry.first << "\t" << entry.second << std::endl;
    }

    return 0;
}
```

